create temp table fix_hit (point text, region_id uuid, grape_id uuid) on commit drop;
with u as (update public.wine_region_grapes set role_note = 'The leading grape of Ajaccio, whose rules require a minimum share of it in reds and rosés.' where region_id = 'd5e5acaa-fbe6-4f72-a5b1-bc7d44c9847c' and grape_id = '52bbda32-443f-4118-898c-51cddc6bd227' and role_note is not distinct from 'At least 40 percent of Ajaccio red plantings.' returning region_id, grape_id) insert into fix_hit select 'R1', * from u;
