with u as (update public.wine_region_grapes set role_note = 'Grown across the valley and above all on the cobbled soils of The Rocks District, where it is the leading grape.' where region_id = 'd9442f2e-617d-4766-8958-01a43e5c1aaa' and grape_id = '3ca91e07-20f0-4993-9b78-a3061bc1ba77' and role_note is not distinct from 'Close to half the vineyard in The Rocks District.' returning region_id, grape_id) insert into fix_hit select 'F19', * from u;
