do $$ begin
  if (select count(*) from fix_hit) <> 41 then
    raise exception 'corrections: % of 41 statements matched; a text changed since 2026-11-23', (select count(*) from fix_hit);
  end if;
end $$;
update public.wine_region_grapes w set local_note = nullif(concat_ws(' ', case when local_name is not null then 'Called ' || local_name || ' here.' end, role_note, taste_note), '')
  where (w.region_id, w.grape_id) in (select distinct region_id, grape_id from fix_hit);
commit;
